import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Modal, ModalHeader, ModalBody, ModalFooter, Input } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { showToast } from 'actions/admin/auth';
import { saveCircularService, saveNoticeBoardService } from 'actions/admin/students';
import { createTimelinePostApi } from 'actions/admin/timeline';
import { timelineUserFor, MAX_CONTENT_CHARS } from 'views/admin/Timeline/timelineUtils';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import {
  buildTimeTable,
  downloadTimeTableSheet,
  examPeriod,
  printHtml,
  timeRange,
  timeTableHtml,
  timeTableImage,
  timeTableText,
} from 'utils/examTimeTable';

const fileSafe = text =>
  String(text || 'exam')
    .trim()
    .replace(/[^a-z0-9]+/gi, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();

const downloadBlob = (blob, name) => {
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
};

const label = { fontSize: 12, color: '#6b778a', fontWeight: 600, marginBottom: 4, display: 'block' };

// The time table of one main exam, one table per class: download it (Excel, picture, print / PDF) or share it - a notice board post or
// a circular (the whole school, the text below), or a post on one class's timeline (guardians of that class, as a picture).
// rows: the subject exams of the main exam (every class), exam: the main exam.
const ExamTimeTableModal = ({ isOpen, onClose, exam, rows }) => {
  const dispatch = useDispatch();
  const token = useSelector(state => state.auth.loggedUserToken);
  const role = useSelector(state => state.auth.loggedUserRole);
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const school = getGlobalSchoolUtils();
  const schoolName = school?.schoolName || '';

  const [classFilter, setClassFilter] = useState('all');
  const [edited, setEdited] = useState(null); // the text after the user changed it, else it follows the table
  const [title, setTitle] = useState('');
  const [confirm, setConfirm] = useState(null); // 'notice' | 'circular' | 'timeline'
  const [busy, setBusy] = useState(false);
  const [pictureClass, setPictureClass] = useState('');
  const confirmRef = useRef(null);
  // the question sits under the buttons, below the visible part of the dialog: bring it into view
  useEffect(() => {
    if (confirm && confirmRef.current) confirmRef.current.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }, [confirm]);

  const allTables = useMemo(() => buildTimeTable(rows, exam?.examDuration), [rows, exam]);
  const tables = useMemo(
    () => (classFilter === 'all' ? allTables : allTables.filter(t => String(t.courseId) === classFilter)),
    [allTables, classFilter]
  );
  const generated = useMemo(() => (exam ? timeTableText(exam, tables, schoolName) : ''), [exam, tables, schoolName]);
  const text = edited === null ? generated : edited;
  const postTitle = title || (exam ? `${exam.examTitle} exam time table` : '');

  // the class whose picture is downloaded / posted to the timeline
  const pictureTable = tables.find(t => String(t.courseId) === pictureClass) || tables[0];
  const timelineUser = timelineUserFor(role, loggedUserId);

  if (!exam) return null;

  const toast = (message, type) => dispatch(showToast(message, type));
  const changeFilter = value => {
    setClassFilter(value);
    setEdited(null);
    setConfirm(null);
  };

  const share = async kind => {
    setBusy(true);
    try {
      if (kind === 'timeline') {
        const blob = await timeTableImage(exam, pictureTable, schoolName, colors.accent);
        const file = new File(
          [blob],
          `${fileSafe(exam.examTitle)}-${fileSafe(pictureTable.courseName)}-time-table.png`,
          {
            type: 'image/png',
          }
        );
        await createTimelinePostApi({
          courseId: pictureTable.courseId,
          user: timelineUser,
          content: `${exam.examTitle} exam time table (${examPeriod(exam)})`.slice(0, MAX_CONTENT_CHARS),
          files: [file],
          token,
        });
        toast(`Posted on the ${pictureTable.courseName} timeline`, 'success');
      } else {
        const postData = { subject: postTitle.trim(), content: text, school: { schoolId: school?.schoolId } };
        await dispatch((kind === 'notice' ? saveNoticeBoardService : saveCircularService)({ postData, token }));
        toast(kind === 'notice' ? 'Posted on the notice board' : 'Circular created', 'success');
      }
      setConfirm(null);
    } catch (err) {
      toast(formResMessage(err), 'error');
    } finally {
      setBusy(false);
    }
  };

  const confirmText = {
    notice: 'Post this on the notice board? Everyone in the school can see it.',
    circular: 'Create a circular with this? Everyone in the school can see it.',
    timeline: `Post the ${
      pictureTable?.courseName || ''
    } exam time table picture on that class's timeline? Its guardians see it in the app.`,
  };
  const shareButton = (kind, name, disabled) => (
    <CustomButton
      size="small"
      variant="outlined"
      name={name}
      disabled={busy || disabled}
      onClick={() => setConfirm(kind)}
    />
  );

  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose} scrollable>
      <ModalHeader toggle={onClose}>
        {exam.examTitle} exam time table
        <div style={{ fontSize: 12, fontWeight: 400, color: '#6b778a' }}>Exam period: {examPeriod(exam)}</div>
      </ModalHeader>
      <ModalBody>
        {!allTables.length ? (
          <div className="text-center text-muted p-3">No subject exams are scheduled yet.</div>
        ) : (
          <>
            {allTables.length > 1 && (
              <div style={{ maxWidth: 320, marginBottom: 12 }}>
                <label style={label}>Show</label>
                <Input type="select" value={classFilter} onChange={e => changeFilter(e.target.value)}>
                  <option value="all">All classes ({allTables.length})</option>
                  {allTables.map(t => (
                    <option key={t.courseId} value={String(t.courseId)}>
                      {t.courseName}
                    </option>
                  ))}
                </Input>
              </div>
            )}

            {tables.map(table => (
              <div key={table.courseId} style={{ marginBottom: 14 }}>
                {table.courseName && <div style={{ fontWeight: 'bold', marginBottom: 6 }}>{table.courseName}</div>}
                <div style={{ overflowX: 'auto', border: '1px solid #e8e3f0', borderRadius: 10 }}>
                  <table className="table table-sm mb-0" style={{ fontSize: 13 }}>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Day</th>
                        <th>Time</th>
                        <th>Subject</th>
                        <th>Hall</th>
                      </tr>
                    </thead>
                    <tbody>
                      {table.entries.map(entry => (
                        <tr key={`${entry.date}-${entry.start}-${entry.subject}`}>
                          <td>{entry.dateLabel}</td>
                          <td>{entry.day}</td>
                          <td>{timeRange(entry)}</td>
                          <td>
                            <b>{entry.subject}</b>
                          </td>
                          <td>{entry.hall}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}

            <div style={{ borderTop: '1px solid #eceff3', paddingTop: 12, marginTop: 4 }}>
              <label style={label}>Download</label>
              <div className="d-flex flex-wrap" style={{ gap: 8, marginBottom: 14 }}>
                <CustomButton
                  size="small"
                  variant="outlined"
                  name="Excel"
                  onClick={() => downloadTimeTableSheet(`${fileSafe(exam.examTitle)}-time-table.xlsx`, exam, tables)}
                />
                <CustomButton
                  size="small"
                  variant="outlined"
                  name="Print / Save as PDF"
                  onClick={() => printHtml(timeTableHtml(exam, tables, schoolName, colors.accent))}
                />
                <CustomButton
                  size="small"
                  variant="outlined"
                  name="Picture (PNG)"
                  onClick={async () =>
                    downloadBlob(
                      await timeTableImage(exam, pictureTable, schoolName, colors.accent),
                      `${fileSafe(exam.examTitle)}-${fileSafe(pictureTable.courseName)}-time-table.png`
                    )
                  }
                />
                {tables.length > 1 && (
                  <span className="d-flex align-items-center" style={{ gap: 6, fontSize: 12 }}>
                    <span className="text-muted">Picture and timeline for</span>
                    <Input
                      type="select"
                      bsSize="sm"
                      style={{ width: 'auto' }}
                      value={String(pictureTable?.courseId)}
                      onChange={e => {
                        setPictureClass(e.target.value);
                        setConfirm(null);
                      }}>
                      {tables.map(t => (
                        <option key={t.courseId} value={String(t.courseId)}>
                          {t.courseName}
                        </option>
                      ))}
                    </Input>
                  </span>
                )}
              </div>

              <label style={label}>Share</label>
              <div className="text-muted" style={{ fontSize: 12, marginBottom: 6 }}>
                Notice board and circular are for the whole school. Check the title and text; you can change them.
              </div>
              <Input
                value={postTitle}
                placeholder="Title"
                onChange={e => setTitle(e.target.value)}
                style={{ marginBottom: 8 }}
              />
              <Input
                type="textarea"
                // tall enough to read the whole text without scrolling (up to about 24 lines), and the user can drag it taller
                rows={10}
                value={text}
                onChange={e => setEdited(e.target.value)}
                style={{
                  fontFamily: 'monospace',
                  fontSize: 13,
                  lineHeight: '20px',
                  // minHeight, not height: the app's stylesheet fixes the height of a text area
                  minHeight: Math.min(520, Math.max(260, (text.split('\n').length + 1) * 20 + 24)),
                  resize: 'vertical',
                  marginBottom: 8,
                }}
              />
              <div className="d-flex flex-wrap" style={{ gap: 8 }}>
                {shareButton('notice', 'Post to notice board', !postTitle.trim() || !text.trim())}
                {shareButton('circular', 'Post as circular', !postTitle.trim() || !text.trim())}
                {shareButton('timeline', 'Post to class timeline', !timelineUser)}
              </div>
              {!timelineUser && (
                <div className="text-muted" style={{ fontSize: 12, marginTop: 6 }}>
                  The class timeline is for school admins and teachers.
                </div>
              )}
              {confirm && (
                <div
                  ref={confirmRef}
                  style={{
                    marginTop: 10,
                    padding: 10,
                    borderRadius: 10,
                    background: '#fff4e0',
                    border: '1px solid #f5b84a',
                    fontSize: 13,
                  }}>
                  {confirmText[confirm]}
                  <div className="d-flex" style={{ gap: 8, marginTop: 8 }}>
                    <CustomButton size="small" name="Yes, post" disabled={busy} onClick={() => share(confirm)} />
                    <CustomButton size="small" variant="outlined" name="Cancel" onClick={() => setConfirm(null)} />
                  </div>
                </div>
              )}
            </div>
          </>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton size="small" variant="outlined" name="Close" onClick={onClose} />
      </ModalFooter>
    </Modal>
  );
};

export default ExamTimeTableModal;
