// Exam types come from the backend enum (GET /api/config/exam-type-multi-select, kept in redux as commonExams).
// Nothing here lists the types: the groups and the labels are worked out from the names the backend sends, so a
// type added to the enum shows up by itself.
//   mid term   MID_TERM, MID_TERM_1, MID_TERM_2 ...  ("Mid Term Exam 1" ...)
//   class test CLASS_TEST
//   main       every other type (Quarter Yearly, Half Yearly, Annual Exam ...)

// Only used when the list could not be fetched, so the screen still works.
const FALLBACK_NAMES = [
  'QUART_YEARLY',
  'HALF_YEARLY',
  'ANUAL_EXAM',
  'MID_TERM_1',
  'MID_TERM_2',
  'MID_TERM_3',
  'MID_TERM_4',
  'CLASS_TEST',
];

// A label sent by the backend (the "label" next to the "name") is used as it is; the label is worked out here only for a name
// that comes without one. Names that do not read right when spelled out from the enum name:
const LABEL_OVERRIDES = { QUART_YEARLY: 'Quarter Yearly', ANUAL_EXAM: 'Annual Exam' };

const MID_TERM_PATTERN = /^MID_TERM(?:_(\d+))?$/;

export const isMidTerm = type => MID_TERM_PATTERN.test(type || '');
export const isClassTest = type => type === 'CLASS_TEST';
export const isMainType = type => !!type && !isMidTerm(type) && !isClassTest(type);

export const examTypeLabel = type => {
  if (!type) return '';
  if (LABEL_OVERRIDES[type]) return LABEL_OVERRIDES[type];
  const midTerm = MID_TERM_PATTERN.exec(type);
  if (midTerm) return midTerm[1] ? `Mid Term Exam ${midTerm[1]}` : 'Mid Term Exam';
  return type
    .toLowerCase()
    .split('_')
    .filter(Boolean)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
};

// { all, main, mid, test }, each a list of { value, label, name } in the order the backend sent them
export const examTypeGroups = commonExams => {
  const entries = (commonExams?.length ? commonExams : FALLBACK_NAMES.map(name => ({ name }))).filter(el => el?.name);
  const all = entries.map(el => {
    const label = el.label || examTypeLabel(el.name);
    return { value: el.name, label, name: label };
  });
  return {
    all,
    main: all.filter(type => isMainType(type.value)),
    mid: all.filter(type => isMidTerm(type.value)),
    test: all.filter(type => isClassTest(type.value)),
  };
};

// The label of one type: the one the backend sent, else the worked-out one
export const examTypeLabelFrom = (commonExams, type) =>
  (commonExams || []).find(el => el?.name === type)?.label || examTypeLabel(type);
