// Pure helpers of the exam time table (views/admin/EmployeeActivities/Marks/components/ExamTimeTableModal): the subject exams of
// one main exam -> one table per class, and that table as a sheet, as plain text for a notice / circular, as printable HTML and as
// a picture (for the class timeline, which takes photos only).
import moment from 'moment';
import * as XLSX from 'xlsx';

// "03:00:00", "3:00", "3" (hours) or 90 -> minutes (0 when it can not be read)
export const durationMinutes = value => {
  const text = String(value == null ? '' : value).trim();
  const clock = text.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (clock) return Number(clock[1]) * 60 + Number(clock[2]);
  const hours = Number(text);
  return Number.isFinite(hours) && text !== '' ? Math.round(hours * 60) : 0;
};

const startOf = row => {
  const day = moment(row.examDate).format('YYYY-MM-DD');
  const time = String(row.examStartTime == null ? '' : row.examStartTime);
  return moment(time.includes('T') ? time : `${day}T${time || '00:00:00'}`);
};

// rows: the subject exams (examSubjectDetails) of one main exam, every class together.
// -> [{ courseId, courseName, entries: [{ date, dateLabel, day, start, end, subject, hall }] }], classes by name, entries by time.
export const buildTimeTable = (rows, durationValue) => {
  const minutes = durationMinutes(durationValue);
  const byCourse = new Map();
  (rows || []).forEach(row => {
    const key = row.course?.courseId ?? 0;
    if (!byCourse.has(key)) {
      byCourse.set(key, { courseId: key, courseName: row.course?.name || '', entries: [] });
    }
    const start = startOf(row);
    const hall = [
      row.examHallName,
      row.examHallCode && row.examHallCode !== row.examHallName ? `(${row.examHallCode})` : '',
    ]
      .filter(Boolean)
      .join(' ');
    byCourse.get(key).entries.push({
      at: start.valueOf(),
      date: moment(row.examDate).format('YYYY-MM-DD'),
      dateLabel: moment(row.examDate).format('DD MMM YYYY'),
      day: moment(row.examDate).format('dddd'),
      start: start.isValid() ? start.format('h:mm A') : '',
      end: start.isValid() && minutes ? start.clone().add(minutes, 'minutes').format('h:mm A') : '',
      subject: row.subject?.name || '',
      hall,
    });
  });
  return [...byCourse.values()]
    .map(course => ({ ...course, entries: course.entries.sort((a, b) => a.at - b.at) }))
    .sort((a, b) => a.courseName.localeCompare(b.courseName, undefined, { numeric: true }));
};

export const timeRange = entry => (entry.end ? `${entry.start} - ${entry.end}` : entry.start);

export const examPeriod = exam =>
  `${moment(exam.startDate).format('DD MMM YYYY')} - ${moment(exam.endDate).format('DD MMM YYYY')}`;

// Plain text for a notice board post / circular / timeline post. Several classes: one block per class.
export const timeTableText = (exam, tables, schoolName) => {
  const lines = [
    `${exam.examTitle} exam time table`,
    schoolName ? `${schoolName}` : '',
    `Exam period: ${examPeriod(exam)}`,
  ];
  tables.forEach(table => {
    lines.push('', table.courseName ? `${table.courseName}` : '');
    table.entries.forEach(entry => {
      lines.push(
        [`${entry.dateLabel} (${entry.day.slice(0, 3)})`, timeRange(entry), entry.subject, entry.hall]
          .filter(Boolean)
          .join(' | ')
      );
    });
  });
  return lines.filter((line, i, all) => !(line === '' && (i === 0 || all[i - 1] === ''))).join('\n');
};

const SHEET_HEAD = ['Class', 'Date', 'Day', 'Time', 'Subject', 'Hall'];
export const timeTableSheetRows = tables =>
  tables.flatMap(table =>
    table.entries.map(entry => [
      table.courseName,
      entry.dateLabel,
      entry.day,
      timeRange(entry),
      entry.subject,
      entry.hall,
    ])
  );

export const downloadTimeTableSheet = (fileName, exam, tables) => {
  const sheet = XLSX.utils.aoa_to_sheet([
    [`${exam.examTitle} exam time table`],
    [`Exam period: ${examPeriod(exam)}`],
    [],
    SHEET_HEAD,
    ...timeTableSheetRows(tables),
  ]);
  sheet['!cols'] = [{ wch: 26 }, { wch: 14 }, { wch: 12 }, { wch: 20 }, { wch: 26 }, { wch: 20 }];
  const book = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(book, sheet, 'Time table');
  XLSX.writeFile(book, fileName);
};

const escapeHtml = text =>
  String(text == null ? '' : text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// A page for the browser's Print / Save as PDF.
export const timeTableHtml = (exam, tables, schoolName, accent = '#7b1fa2') => {
  const blocks = tables
    .map(
      table => `
    <section>
      ${table.courseName ? `<h2>${escapeHtml(table.courseName)}</h2>` : ''}
      <table>
        <thead><tr><th>Date</th><th>Day</th><th>Time</th><th>Subject</th><th>Hall</th></tr></thead>
        <tbody>${table.entries
          .map(
            entry =>
              `<tr><td>${escapeHtml(entry.dateLabel)}</td><td>${escapeHtml(entry.day)}</td><td>${escapeHtml(
                timeRange(entry)
              )}</td><td><b>${escapeHtml(entry.subject)}</b></td><td>${escapeHtml(entry.hall)}</td></tr>`
          )
          .join('')}</tbody>
      </table>
    </section>`
    )
    .join('');
  return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(exam.examTitle)} exam time table</title>
<style>
  body { font-family: Arial, sans-serif; color: #222; margin: 28px; }
  h1 { margin: 0; font-size: 22px; color: ${accent}; } .sub { color: #555; margin: 4px 0 18px; font-size: 13px; }
  h2 { font-size: 16px; margin: 22px 0 8px; } section { page-break-inside: avoid; }
  table { border-collapse: collapse; width: 100%; font-size: 13px; }
  th { background: ${accent}; color: #fff; text-align: left; } th, td { border: 1px solid #cfc3da; padding: 7px 9px; }
  tr:nth-child(even) td { background: #f7f2fb; }
</style></head><body>
  <h1>${escapeHtml(schoolName || '')}</h1>
  <div class="sub"><b>${escapeHtml(exam.examTitle)} exam time table</b> &nbsp;|&nbsp; Exam period: ${escapeHtml(
    examPeriod(exam)
  )}</div>
  ${blocks}
</body></html>`;
};

// Opens the print dialog for html without leaving the page (a hidden frame, so no pop-up is blocked).
export const printHtml = html => {
  const frame = document.createElement('iframe');
  frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;';
  document.body.appendChild(frame);
  frame.contentDocument.open();
  frame.contentDocument.write(html);
  frame.contentDocument.close();
  setTimeout(() => {
    frame.contentWindow.focus();
    frame.contentWindow.print();
    setTimeout(() => frame.remove(), 1500);
  }, 250);
};

// The time table of ONE class drawn as a picture (png Blob). Drawn by hand on a canvas: no library needed.
export const timeTableImage = (exam, table, schoolName, accent = '#7b1fa2') => {
  const scale = 2;
  const width = 900;
  const rowHeight = 40;
  const head = 118;
  const columns = [
    ['Date', 24, 170],
    ['Day', 194, 120],
    ['Time', 314, 190],
    ['Subject', 504, 230],
    ['Hall', 734, 150],
  ];
  const height = head + 44 + table.entries.length * rowHeight + 52;
  const canvas = document.createElement('canvas');
  canvas.width = width * scale;
  canvas.height = height * scale;
  const ctx = canvas.getContext('2d');
  ctx.scale(scale, scale);
  const fit = (text, max) => {
    let out = String(text || '');
    while (out.length > 1 && ctx.measureText(out).width > max) out = `${out.slice(0, -2)}…`;
    return out;
  };
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = accent;
  ctx.fillRect(0, 0, width, head - 18);
  ctx.fillStyle = '#ffffff';
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 26px Arial';
  ctx.fillText(fit(`${exam.examTitle} exam time table`, width - 48), 24, 34);
  ctx.font = '16px Arial';
  ctx.fillText(fit([schoolName, table.courseName].filter(Boolean).join('  |  '), width - 48), 24, 66);
  ctx.fillText(`Exam period: ${examPeriod(exam)}`, 24, 88);
  const top = head;
  ctx.fillStyle = '#efe5f6';
  ctx.fillRect(0, top, width, 44);
  ctx.fillStyle = '#4a148c';
  ctx.font = 'bold 15px Arial';
  columns.forEach(([label, x]) => ctx.fillText(label, x, top + 22));
  table.entries.forEach((entry, i) => {
    const y = top + 44 + i * rowHeight;
    if (i % 2) {
      ctx.fillStyle = '#f9f5fc';
      ctx.fillRect(0, y, width, rowHeight);
    }
    ctx.fillStyle = '#222222';
    const cells = [entry.dateLabel, entry.day, timeRange(entry), entry.subject, entry.hall];
    columns.forEach(([, x, max], c) => {
      ctx.font = c === 3 ? 'bold 15px Arial' : '15px Arial';
      ctx.fillText(fit(cells[c], max - 12), x, y + rowHeight / 2);
    });
    ctx.fillStyle = '#e4d9ec';
    ctx.fillRect(0, y + rowHeight - 1, width, 1);
  });
  ctx.fillStyle = '#7a7a7a';
  ctx.font = '13px Arial';
  ctx.fillText('Shared from Scholae', 24, height - 24);
  return new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
};
