import React from 'react';
import { UncontrolledDropdown, DropdownToggle, DropdownMenu, DropdownItem } from 'reactstrap';
import MoreHorizIcon from '@material-ui/icons/MoreHoriz';

// The "More" menu: one small three-dot button that opens the less used actions of a row, a card or a page, instead of a long row of
// buttons. Keep the one action people use all the time as a real button next to it, and put the rest here.
// items: [{ label, onClick, danger?, hidden? }]. A hidden item is left out; nothing is drawn when no item is left.
// The look (button, menu, hover colour) is in theme/richUi.css (.rui-more, .dropdown-item), so every menu in the app matches.
const ActionMenu = ({ items, label = 'More', style }) => {
  const shown = (items || []).filter(item => item && !item.hidden);
  if (!shown.length) return null;
  return (
    <UncontrolledDropdown style={{ display: 'inline-block', ...style }}>
      <DropdownToggle tag="button" type="button" className="rui-more" aria-label={label} title={label}>
        <MoreHorizIcon style={{ fontSize: 20 }} />
      </DropdownToggle>
      {/* positionFixed: the menu is not clipped by a table or card with its own overflow, and it never adds a small inner scroll to it */}
      <DropdownMenu right positionFixed>
        {shown.map(item => (
          <DropdownItem key={item.label} className={item.danger ? 'rui-danger' : undefined} onClick={item.onClick}>
            {item.label}
          </DropdownItem>
        ))}
      </DropdownMenu>
    </UncontrolledDropdown>
  );
};

export default ActionMenu;
